  def admission_update(entry_id, token:, note:, generation: timekeeping_arrange.current_generation)
    described_class.new.call(build_entry_command(:update, token:, entry_id:, generation:, body: { "note" => note }))
  end

  def admission_create(project:, token:, generation:, key: SecureRandom.uuid)
    body = { "project_id" => project, "work_date" => "2026-03-02", "duration" => 30.0, "note" => "Planning",
             "source" => "manual", "source_metadata" => {} }
    described_class.new.call(build_entry_command(:create, token:, body:, generation:, key:))
  end

  # "While fenced, Timekeeping refuses every entry write at every generation with stale_generation, including for a company it has never seen"
  # An empty or non-numeric header must be refused too, never raise and never match a null generation.
  it "refuses every write for an existing company while fenced, whatever generation header it carries, and writes nothing" do
    entry_id = timekeeping_arrange.entry(company:, user: owner, project:)
    expect(admission_update(entry_id, token:, note: "Seeded").status).to eq(200)
    baseline = entry_write_counts
    expect(baseline).to include(entries: 1, audit_events: 1, outbox_snapshots: 1, idempotency_receipts: 1, versions: 2)

    Timekeeping::Admission.fence!(lock_timeout: 1)

    [1, 2, 0, "", "abc"].each do |generation|
      expect(admission_answer(admission_update(entry_id, token:, note: "Fenced", generation:))).to eq(stale),
        "update with header #{generation.inspect} was not refused"
      expect(entry_write_counts).to eq(baseline)
    end
    [1, 2].each do |generation|
      expect(admission_answer(admission_create(project:, token:, generation:))).to eq(stale)
      expect(entry_write_counts).to eq(baseline)
    end
    expect(Entry.find(entry_id).note).to eq("Seeded")
    expect(Timekeeping::Admission.current.generation).to be_nil
  end

  # "While fenced, Timekeeping refuses every entry write at every generation with stale_generation, including for a company it has never seen"
  it "refuses a delete, a bulk move and a bulk delete while fenced and leaves the entries as stored" do
    entry_ids = Array.new(2) { timekeeping_arrange.entry(company:, user: owner, project:) }
    other_project = timekeeping_arrange.project(company:)
    stored = Entry.where(id: entry_ids).order(:id).map(&:attributes)
    baseline = entry_write_counts
    expect(baseline).to include(entries: 2, versions: 2)
    Timekeeping::Admission.fence!(lock_timeout: 1)
    commands = lambda do |generation|
      [build_entry_command(:destroy, token:, entry_id: entry_ids.first, generation:),
       build_entry_command(:bulk_move, token:, generation:,
                                       body: { "entry_ids" => entry_ids, "project_id" => other_project }),
       build_entry_command(:bulk_delete, token:, generation:, body: { "entry_ids" => entry_ids })]
    end

    [1, 2].each do |generation|
      commands.call(generation).each do |command|
        expect(admission_answer(described_class.new.call(command))).to eq(stale),
          "#{command.route} at #{generation} was not refused"
        expect(entry_write_counts).to eq(baseline)
      end
    end
    expect(Entry.where(id: entry_ids).order(:id).map(&:attributes)).to eq(stored)
  end

  # "While fenced, Timekeeping refuses every entry write at every generation with stale_generation, including for a company it has never seen"
  it "refuses a create for a company never seen before while fenced and creates no rows or admission state" do
    Timekeeping::Admission.fence!(lock_timeout: 1)
    expect(Entry.where(company_id: company).count).to eq(0)
    baseline = entry_write_counts

    [1, 2, 0, "", "abc"].each do |generation|
      expect(admission_answer(admission_create(project:, token:, generation:))).to eq(stale),
        "create with header #{generation.inspect} was not refused"
      expect(entry_write_counts).to eq(baseline)
    end
    expect(Entry.where(company_id: company).count).to eq(0)
    expect(Timekeeping::Admission.count).to eq(1)
    expect(Timekeeping::Admission.current.generation).to be_nil
  end

  # A refusal must leave no idempotency receipt; otherwise a retry with the
  # same key after re-admission would replay the stored 409 instead of writing.
  it "stores no receipt for a write refused while fenced, so a retry is refused again and the same key writes once after admit!" do
    key = SecureRandom.uuid
    Timekeeping::Admission.fence!(lock_timeout: 1)
    expect(Entry.where(company_id: company).count).to eq(0)
    baseline = entry_write_counts

    refused = admission_create(project:, token:, generation: 4, key:)
    retried_while_fenced = admission_create(project:, token:, generation: 4, key:)

    expect(admission_answer(refused)).to eq(stale)
    expect(admission_answer(retried_while_fenced)).to eq(stale)
    expect(entry_write_counts).to eq(baseline)
    expect(IdempotencyReceipt.count).to eq(0)
    expect(Timekeeping::Admission.current.generation).to be_nil

    Timekeeping::Admission.admit!(generation: 4)
    written = admission_create(project:, token:, generation: 4, key:)
    replayed = admission_create(project:, token:, generation: 4, key:)

    expect(written.status).to eq(201)
    expect([replayed.status, replayed.body]).to eq([written.status, written.body])
    expect(entry_write_counts.slice(:entries, :audit_events, :outbox_snapshots, :idempotency_receipts))
      .to eq(entries: 1, audit_events: 1, outbox_snapshots: 1, idempotency_receipts: 1)
  end

  # "After re-admission at a generation, only that generation is accepted"
  # "After `admit!(generation: 4)`, a write carrying 4 succeeds and one carrying 3 is refused."
  # 5 is also refused, so the check is equality and not "at least".
  it "accepts only generation 4 after admit!(generation: 4) and stamps 4 on the outbox row" do
    entry_id = timekeeping_arrange.entry(company:, user: owner, project:)
    Timekeeping::Admission.fence!(lock_timeout: 1)
    Timekeeping::Admission.admit!(generation: 4)
    baseline = entry_write_counts

    [3, 5].each do |generation|
      expect(admission_answer(admission_update(entry_id, token:, note: "Stale #{generation}", generation:))).to eq(stale)
      expect(entry_write_counts).to eq(baseline)
    end

    admitted = admission_update(entry_id, token:, note: "Admitted", generation: 4)

    expect(admitted.status).to eq(200)
    expect(Entry.find(entry_id).note).to eq("Admitted")
    expect(OutboxSnapshot.where(id: entry_id).pluck(:generation)).to eq([4])
    expect(Timekeeping::Admission.current.generation).to eq(4)
  end

  # "After re-admission at a generation, only that generation is accepted"
  it "refuses writes carrying 4 and accepts only 6 after a second admission at 6 follows one at 4" do
    entry_id = timekeeping_arrange.entry(company:, user: owner, project:)
    Timekeeping::Admission.fence!(lock_timeout: 1)
    Timekeeping::Admission.admit!(generation: 4)
    Timekeeping::Admission.fence!(lock_timeout: 1)
    Timekeeping::Admission.admit!(generation: 6)
    baseline = entry_write_counts

    expect(admission_answer(admission_update(entry_id, token:, note: "Stale", generation: 4))).to eq(stale)
    expect(entry_write_counts).to eq(baseline)
    expect(Timekeeping::Admission.current.generation).to eq(6)

    expect(admission_update(entry_id, token:, note: "Current", generation: 6).status).to eq(200)
    expect(Entry.find(entry_id).note).to eq("Current")
  end

  # "Give the Timekeeping application (`timekeeping/`) one stored admission state: it admits entry writes at
  # exactly one generation, or at none while fenced."
  it "applies one admitted generation to companies arranged before and after the admission, with a single admission row" do
    company_before = timekeeping_arrange.company
    Timekeeping::Admission.admit!(generation: 4)
    company_after = timekeeping_arrange.company

    [company_before, company_after].each do |each_company|
      each_token = timekeeping_arrange.token_for(timekeeping_arrange.user(company: each_company, role: "owner"))

      admitted = admission_create(project: timekeeping_arrange.project(company: each_company), token: each_token, generation: 4)
      refused = admission_create(project: timekeeping_arrange.project(company: each_company), token: each_token, generation: 3)

      expect(admitted.status).to eq(201)
