    end
    expect(Timekeeping::Admission.count).to eq(1)
    expect(Timekeeping::Admission.current.generation).to eq(4)
  end

  # "The fence stays in place until a later admission"
  it "keeps the fence through refused writes and lifts it only when admit! is called again" do
